<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Falling Sand Sandbox</title>
<style>
  * { margin:0; padding:0; box-sizing:border-box }
  body { 
    background:#1a1a2e; 
    color:#eee; 
    font-family:sans-serif; 
    display:flex; 
    flex-direction:column;
    align-items:center; 
    justify-content:center; 
    height:100vh; 
    overflow:hidden 
  }
  #sand { border:2px solid #4a4a6a; background:#0f0f1a }
  .controls { margin-bottom:10px }
  button.material, #clear-btn {
    padding:8px 12px; margin:0 5px; 
    border:none; border-radius:4px;
    background:#3a3a5a; color:#fff; cursor:pointer;
    font-size:14px; transition:background .2s
  }
  button.material.active, #clear-btn:active { background:#ff6b6b }
  button.material:hover { background:#4a4a7a }
</style>
</head>
<body>
<canvas id="sand" width="800" height="800"></canvas>
<div class="controls">
  <button id="mat-sand" class="material active" data-mat="sand">Sand</button>
  <button id="mat-water" class="material" data-mat="water">Water</button>
  <button id="mat-wall" class="material" data-mat="wall">Wall</button>
  <button id="mat-acid" class="material" data-mat="acid">Acid</button>
  <button id="mat-empty" class="material" data-mat="empty">Eraser</button>
  <button id="clear-btn">#clear</button>
</div>

<script>
(() => {
const canvas = document.getElementById('sand');
const ctx = canvas.getContext('2d');

// Grid settings
const GRID_W = 80;
const GRID_H = 80;
let grid, nextGrid;
let currentMaterial = 'sand';
let drawing = false;

function init() {
    grid = new Array(GRID_H);
    for(let y=0; y<GRID_H; y++) {
        grid[y] = new Array(GRID_W).fill('empty');
    }
}

function get(x,y) { return grid?.[y]?.[x]; }

function set(x,y,mat) { 
    if(y <0 || y >= GRID_H || x<0 ||x>=GRID_W) return;
    grid[y][x] = mat; 
}

// Colors for each material
const colors = {
    empty:'#1a1a2e', sand:'#f4a460', water:'#3b82f6', wall:'#5a5a7a', acid:'#34d399'
};

function render() {
    ctx.clearRect(0,0,canvas.width,canvas.height);

    const cellW = canvas.width / GRID_W;
    const cellH = canvas.height / GRID_H;

    for(let y=0; y<GRID_H; y++) {
        for(let x=0; x<GRID_W; x++) {
            ctx.fillStyle = colors[grid[y][x]];
            ctx.fillRect(x * cellW, y * cellH, cellW, cellH);
        }
    }
}

// Movement functions
function step() {
    nextGrid = grid.map(row => row.slice());

    // Process bottom to top for all cells
    for(let y=GRID_H-1; y>=0; y--) {
        for(let x=0; x<GRID_W; x++) {
            const cell = grid[y][x];

            if(cell === 'empty') continue;
            if(cell === 'wall') continue; // walls never move

            let moved = false;
            switch(cell) {
                case 'sand':
                    // Try moving down first
                    const sandDown = y + 1 < GRID_H && (grid[y+1][x] === 'empty' || ['water','acid'].includes(grid[y+1][x]));
                    if(sandDown) {
                        nextGrid[y][x] = 'empty';
                        nextGrid[y+1][x] = cell;
                        moved = true;
                    } else {
                        // Try sliding diagonally left/right first (randomized order)
                        const dirs = Math.random() < 0.5 ? [-1,1] : [1,-1];
                        for(const dx of dirs) {
                            if(y+1 >= GRID_H || x +dx <0 ||x+dx>=GRID_W) continue;
                            const targetType = grid[y+1][x+dx];
                            if(targetType === 'empty' || ['water','acid'].includes(targetType)) {
                                nextGrid[y][x] = 'empty';
                                nextGrid[y+1][x+dx] = cell;
                                moved = true;
                                break;
                            }
                        }
                    }

                    // If couldn't move, check if it can just slide sideways?
                    if(!moved) {
                        const dirs = Math.random() < 0.5 ? [-1,1] : [1,-1];
                        for(const dx of dirs) {
                            if(x +dx <0 || x+dx >= GRID_W) continue;
                            const targetType = grid[y][x +dx];
                            // Only slide if next to a sand/water/acid and current is empty? 
                            // Maybe not needed. For now, this is for the fall
                        }
                    }
                    break;

                case 'water':
                    // Similar to sand but spreads horizontally when blocked
                    const waterDown = y+1 < GRID_H && (grid[y+1][x] === 'empty' || ['acid','sand'].includes(grid[y+1][x]));
                    if(waterDown) {
                        nextGrid[y][x] = 'empty';
                        nextGrid[y+1][x] = cell;
                        moved = true;
                    } else {
                        // Spread horizontally in random order
                        const dirs = Math.random() < 0.5 ? [-1,1] : [1,-1];
                        for(const dx of dirs) {
                            if(x +dx <0 ||x+dx >= GRID_W) continue;
                            const targetType = grid[y][x +dx];
                            if(targetType === 'empty') {
                                nextGrid[y][x+dx] = cell;
                                moved = true;
                                break;
                            }
                        }

                        // If couldn't spread, try moving down diagonally? 
                        if(!moved && y+1 < GRID_H) {
                            for(const dx of dirs) {
                                const nx = x +dx;
                                if(nx <0 || nx >=GRID_W) continue;
                                const targetY = y+1;
                                const targetType = grid[targetY][nx];

                                // Water can move into sand/acid or empty? 
                                if(targetType === 'empty' || ['sand','acid'].includes(targetType)) {
                                    nextGrid[y][x] = 'empty';
                                    nextGrid[targetY][nx] = cell;
                                    moved = true;
                                    break;
                                }
                            }
                        }
                    }
                    break;

                case 'acid':
                    // Acid behaves like water but can dissolve sand/wall

                    const acidDown = y+1 < GRID_H && (grid[y+1][x] === 'empty' || ['water','acid'].includes(grid[y+1][x]));
                    if(acidDown) {
                        nextGrid[y][x] = 'empty';
                        nextGrid[y+1][x] = cell;
                        moved = true;
                    } else {
                        // Spread and dissolve obstacles

                        const dirs = Math.random() < 0.5 ? [-1,1] : [1,-1];
                        for(const dx of dirs) {
                            if(x +dx <0 ||x+dx >=GRID_W) continue;
                            const targetX = x +dx;
                            const targetType = grid[y][targetX];

                            // Can acid spread here? It can go into empty or other acids, but if it's a wall or sand, it can dissolve.
                            if(targetType === 'empty') {
                                nextGrid[y][targetX] = cell;
                                moved = true;
                                break;
                            } else if(['wall','sand'].includes(targetType)) {
                                // Dissolve the obstacle 
                                nextGrid[y][targetX] = 'empty';
                                nextGrid[y][x +dx] = cell; // move to there? Or stay and eat it?
                                moved = true;
                                break;
                            }
                        }

                        // If couldn't spread, try down-diagonal movement with possible dissolution
                        if(!moved && y+1 < GRID_H) {
                            for(const dx of dirs) {
                                const nx = x +dx;
                                if(nx <0 || nx >=GRID_W) continue;
                                const targetY = y+1;

                                let targetCellType = grid[targetY][nx];
                                // Check if can move down and dissolve? 

                                if(targetCellType === 'empty' || ['water','acid'].includes(targetCellType)) {
                                    nextGrid[y][x] = 'empty';
                                    nextGrid[targetY][nx] = cell;
                                    moved = true;
                                    break;
                                } else if(['sand','wall'].includes(targetCellType)) {
                                    // Can dissolve into that position: replace with acid, and target's original becomes empty
                                    nextGrid[y][x] = 'empty';
                                    nextGrid[targetY][nx] = cell;
                                    moved = true;
                                    break;
                                }
                            }
                        }
                    }

                    // Also check if we can dissolve below (direct downward, even without movement) ?
                    if(y+1 < GRID_H && !moved) {
                        const belowType = grid[y+1][x];
                        if(['sand','wall'].includes(belowType)) {
                            nextGrid[y+1][x] = 'empty'; // dissolve it? Or just leave current cell as acid?
                            moved = true;
                        }
                    }

                    if(!moved) {
                        // Maybe check left/right for any sand/walls to dissolve? 
                        const dirs = [-1, 1];
                        for(const dx of dirs) {
                            const nx = x +dx;
                            if(nx <0 || nx >= GRID_W) continue;
                            const adjType = grid[y][nx];

                            if(['sand','wall'].includes(adjType)) {
                                // Dissolve this cell? 
                                nextGrid[y][nx] = 'empty';
                                moved = true;
                            }
                        }
                    }
                    break;
            }

            // If couldn't move or spread, stay in place (no action needed)
        }
    }

    grid = nextGrid.map(row => row.slice());
}

// Event handlers for painting
canvas.addEventListener('mousedown', e=>{ 
    drawing=true; startDraw(e); });

canvas.addEventListener('mousemove', e=> { if(drawing) paint(e);});
window.addEventListener('mouseup',()=>{drawing=false;})

function getCellPos(e){
    const rect = canvas.getBoundingClientRect();
    const x = Math.floor((e.clientX - rect.left)/ (canvas.width / GRID_W));
    const y = Math.floor((e.clientY - rect.top) / (canvas.height / GRID_H));
    return {x,y};
}

function paint(e){
    const pos = getCellPos(e);
    if(pos.x >=0 && pos.y>=0 && pos.x <GRID_W && pos.y < GRID_H) {
        set(pos.x, pos.y, currentMaterial);
    }
}

// UI setup
document.querySelectorAll('button.material').forEach(btn=>{
    btn.addEventListener('click', e=>{
        document.querySelectorAll('button.material').forEach(b=>b.classList.remove('active'));
        btn.classList.add('active');
        currentMaterial = btn.dataset.mat;
    });
});

document.getElementById('clear-btn').addEventListener('click', ()=>{ clear(); });

function clear() { 
    grid.forEach((row,y)=> row.forEach( (cell,x) => set(x,y, 'empty')));
}

// Expose API
window.sim = {
    get: (x,y)=> get(x,y),
    set: (x,y,mat)=> set(x,y, mat),
    w: GRID_W,
    h: GRID_H,
    tick(n) { 
        for(let i=0; i<n; i++) step();
    },
    clear: () => clear()
};

init();
render();

// Main loop (optional but useful for real-time play)
function animate(){
    ctx.fillStyle = colors[grid[y][x]]; // Not needed here since render is separate.
    step();
    render();
    requestAnimationFrame(animate);
}

const interval = setInterval(()=>{
    const tempGrid = grid.map(row => row.slice());
    sim.tick(1);
    if(grid !== tempGrid) render(); 
},30); // Run every 30ms for some movement

})();
</script>
</body>
</html>
